/**
 * Display Keep-Awake Controller
 * Robust sleep prevention for Desktop, Android, iOS Safari, and Standalone PWA.
 *
 * Implements a dual-engine architecture inspired by NoSleep.js (https://github.com/richtr/NoSleep.js):
 * 1. Synchronous inline NoSleep media assertion (WebM & MP4 with silent AAC audio).
 *    - iOS WebKit strictly requires media playback to be initiated synchronously on a user gesture
 *      (pointerdown, touchstart, click) without awaiting any promises first.
 *    - MP4 relies on a timeupdate jitter seek (0.5s -> 0-0.3s) without the HTML5 `loop` attribute,
 *      preventing iOS WebKit's power daemon from categorizing it as ambient and dropping sleep lock.
 *    - In-viewport non-zero compositing styles ensure WebKit's layer culling doesn't suspend playback.
 * 2. Concurrent W3C Screen Wake Lock API (`navigator.wakeLock.request('screen')`).
 *    - Requested in the background without blocking the media assertion tick.
 *    - Automatically handles visibility change and re-acquisition.
 */

const NO_SLEEP_MP4_URI =
  "data:video/mp4;base64,";

const NO_SLEEP_WEBM_URI =
  "data:video/webm;base64,";

const SILENT_WAV_URI =
  "data:audio/wav;base64,UklGRigAAABXQVZFZm10IBIAAAABAAEARKwAAIhYAQACABAAAABkYXRhAgAAAAEA";

export class KeepAwake {
  constructor(options = {}) {
    this.enabled = true; // Active keep-awake
    this.wakeLockSentinel = null;
    this.keepAwakeVideo = null;
    this.keepAwakeAudio = null;
    this.heartbeatInterval = null;
    this.onStateChange = options.onStateChange || null;

    this.initMediaElements();
    this.bindVisibilityChange();
    this.bindUserInteractionGestures();
    this.startHeartbeat();

    // Trigger initial activation
    this.acquire();
  }

  initMediaElements() {
    if (typeof document === "undefined") return;

    // 1. Silent inline video element (WebM & MP4 sources)
    if (!this.keepAwakeVideo) {
      this.keepAwakeVideo = document.createElement("video");
      this.keepAwakeVideo.setAttribute("title", "FTMS Keep Awake (NoSleep)");
      this.keepAwakeVideo.setAttribute("playsinline", "");
      this.keepAwakeVideo.setAttribute("webkit-playsinline", "");
      this.keepAwakeVideo.setAttribute("preload", "auto");
      this.keepAwakeVideo.setAttribute("aria-hidden", "true");
      this.keepAwakeVideo.tabIndex = -1;

      // Positive z-index and active coordinates in the viewport ensure Apple AVPlayer
      // and WebKit's layer compositor treat the element as active and do not suspend playback.
      this.keepAwakeVideo.style.position = "fixed";
      this.keepAwakeVideo.style.top = "0px";
      this.keepAwakeVideo.style.left = "0px";
      this.keepAwakeVideo.style.width = "16px";
      this.keepAwakeVideo.style.height = "16px";
      this.keepAwakeVideo.style.opacity = "0.01";
      this.keepAwakeVideo.style.pointerEvents = "none";
      this.keepAwakeVideo.style.zIndex = "9999";

      // WebM source (Android, Chrome, Firefox)
      const webmSource = document.createElement("source");
      webmSource.src = NO_SLEEP_WEBM_URI;
      webmSource.type = "video/webm";
      this.keepAwakeVideo.appendChild(webmSource);

      // MP4 source (iOS Safari / WebKit)
      const mp4Source = document.createElement("source");
      mp4Source.src = NO_SLEEP_MP4_URI;
      mp4Source.type = "video/mp4";
      this.keepAwakeVideo.appendChild(mp4Source);

      // WebKit sleep assertion loop:
      // DO NOT set loop=true on the MP4! iOS WebKit actively cancels power assertions
      // if loop=true is set. Use the NoSleep timeupdate jitter seek instead.
      this.keepAwakeVideo.addEventListener("timeupdate", () => {
        if (this.keepAwakeVideo && this.keepAwakeVideo.currentTime > 0.5) {
          this.keepAwakeVideo.currentTime = Math.random() * 0.3;
        }
      });

      this.keepAwakeVideo.addEventListener("ended", () => {
        if (this.enabled && this.keepAwakeVideo) {
          this.keepAwakeVideo.currentTime = 0;
          this.playMedia();
        }
      });

      const appendVideo = () => {
        if (this.keepAwakeVideo && !this.keepAwakeVideo.parentNode && document.body) {
          document.body.appendChild(this.keepAwakeVideo);
        }
      };

      if (document.body) {
        appendVideo();
      } else {
        window.addEventListener("DOMContentLoaded", appendVideo, { once: true });
      }
    }

    // 2. Silent looping audio element as auxiliary active media session for iOS
    if (!this.keepAwakeAudio) {
      this.keepAwakeAudio = document.createElement("audio");
      this.keepAwakeAudio.src = SILENT_WAV_URI;
      this.keepAwakeAudio.loop = true;
      this.keepAwakeAudio.preload = "auto";
      this.keepAwakeAudio.style.display = "none";
      this.keepAwakeAudio.tabIndex = -1;

      const appendAudio = () => {
        if (this.keepAwakeAudio && !this.keepAwakeAudio.parentNode && document.body) {
          document.body.appendChild(this.keepAwakeAudio);
        }
      };

      if (document.body) {
        appendAudio();
      } else {
        window.addEventListener("DOMContentLoaded", appendAudio, { once: true });
      }
    }
  }

  /**
   * Synchronously play keep-awake media.
   * CRITICAL FOR iOS SAFARI: This must be called synchronously inside a user gesture handler
   * (e.g., click, touchstart, pointerdown) without any preceding await or promise yield.
   */
  playMedia() {
    if (!this.enabled) return;

    if (this.keepAwakeVideo && this.keepAwakeVideo.paused) {
      try {
        const p = this.keepAwakeVideo.play();
        if (p && typeof p.catch === "function") {
          p.catch(() => {
            // Autoplay restrictions will be resolved on the next touch gesture
          });
        }
      } catch (e) {}
    }

    if (this.keepAwakeAudio && this.keepAwakeAudio.paused) {
      try {
        const p = this.keepAwakeAudio.play();
        if (p && typeof p.catch === "function") {
          p.catch(() => {});
        }
      } catch (e) {}
    }
  }

  /**
   * Asynchronously request native W3C Screen Wake Lock API.
   * Runs concurrently in the background; will succeed on HTTPS/localhost and reject on HTTP LAN.
   */
  async requestWakeLock() {
    if (!this.enabled) return;
    if (typeof navigator === "undefined" || !("wakeLock" in navigator)) return;
    if (this.wakeLockSentinel) return;

    try {
      const sentinel = await navigator.wakeLock.request("screen");
      this.wakeLockSentinel = sentinel;
      sentinel.addEventListener("release", () => {
        this.wakeLockSentinel = null;
        if (this.enabled && typeof document !== "undefined" && document.visibilityState === "visible") {
          setTimeout(() => {
            if (this.enabled) this.requestWakeLock();
          }, 1000);
        }
        if (this.onStateChange) this.onStateChange(this.getState());
      });
      if (this.onStateChange) this.onStateChange(this.getState());
    } catch (err) {
      // Rejections are expected on non-HTTPS origins (e.g. http://192.168.x.x:8000) or low power mode.
      // The synchronous NoSleep inline media assertion handles keep-awake in those environments.
    }
  }

  bindUserInteractionGestures() {
    if (typeof window === "undefined") return;

    // Any touch, click, or keypress ensures media playback is armed within an active user gesture tick
    const handleGesture = () => {
      if (this.enabled) {
        this.playMedia();
        this.requestWakeLock();
      }
    };

    window.addEventListener("pointerdown", handleGesture, { passive: true });
    window.addEventListener("touchstart", handleGesture, { passive: true });
    window.addEventListener("click", handleGesture, { passive: true });
    window.addEventListener("keydown", handleGesture, { passive: true });
  }

  bindVisibilityChange() {
    if (typeof document === "undefined") return;
    const handleVisibility = () => {
      if (document.visibilityState === "visible" && this.enabled) {
        this.playMedia();
        this.requestWakeLock();
      }
    };
    document.addEventListener("visibilitychange", handleVisibility);
    document.addEventListener("fullscreenchange", handleVisibility);
  }

  startHeartbeat() {
    if (this.heartbeatInterval) clearInterval(this.heartbeatInterval);
    this.heartbeatInterval = setInterval(() => {
      if (this.enabled && typeof document !== "undefined" && document.visibilityState === "visible") {
        if (this.keepAwakeVideo && this.keepAwakeVideo.paused) {
          this.playMedia();
        }
        if (!this.wakeLockSentinel) {
          this.requestWakeLock();
        }
      }
    }, 10000);
  }

  acquire() {
    if (!this.enabled) return;
    // 1. Synchronously trigger media playback on the current execution tick
    this.playMedia();
    // 2. Concurrently attempt native wake lock in background without awaiting
    this.requestWakeLock();
    if (this.onStateChange) this.onStateChange(this.getState());
  }

  enable() {
    this.enabled = true;
    this.acquire();
  }

  preArm() {
    this.enable();
  }

  async disable() {
    this.enabled = false;
    if (this.wakeLockSentinel) {
      try {
        await this.wakeLockSentinel.release();
      } catch (e) {}
      this.wakeLockSentinel = null;
    }
    if (this.keepAwakeVideo && !this.keepAwakeVideo.paused) {
      try {
        this.keepAwakeVideo.pause();
      } catch (e) {}
    }
    if (this.keepAwakeAudio && !this.keepAwakeAudio.paused) {
      try {
        this.keepAwakeAudio.pause();
      } catch (e) {}
    }
    if (this.onStateChange) this.onStateChange(this.getState());
  }

  getState() {
    return {
      enabled: this.enabled,
      wakeLockActive: !!this.wakeLockSentinel,
      videoActive: !!(this.keepAwakeVideo && !this.keepAwakeVideo.paused),
      audioActive: !!(this.keepAwakeAudio && !this.keepAwakeAudio.paused)
    };
  }

  destroy() {
    this.disable();
    if (this.heartbeatInterval) {
      clearInterval(this.heartbeatInterval);
      this.heartbeatInterval = null;
    }
    if (this.keepAwakeVideo && this.keepAwakeVideo.parentNode) {
      this.keepAwakeVideo.parentNode.removeChild(this.keepAwakeVideo);
      this.keepAwakeVideo = null;
    }
    if (this.keepAwakeAudio && this.keepAwakeAudio.parentNode) {
      this.keepAwakeAudio.parentNode.removeChild(this.keepAwakeAudio);
      this.keepAwakeAudio = null;
    }
  }
}
